#include <cstdint>
#include <cstdio>

int main() {
    int8_t  pnl   = -75;                 // signed 8-bit: PnL can be negative
    uint8_t ticks = 200;                 // unsigned 8-bit: wraps modulo 256
    ticks = ticks + 100;                 // 300 mod 256 = 44 - silent wrap
    std::printf("pnl=%d ticks=%d\n", pnl, ticks);
    return 0;
}

